function S({registerIndicator:I,nulls:h}){I({id:"oa-dx",name:"Directional Movement Index (DX)",category:"Dynamics",placement:"pane",inputs:[{key:"period",type:"number",label:"Period",default:14,min:1,max:5e3,step:1,tooltip:"Number of bars used in the calculation."}],plots:[{key:"dx",type:"line",title:"DX",style:{color:"#ffeb3b",lineWidth:2}},{key:"plusDi",type:"line",title:"+DI",style:{color:"#4caf50",lineWidth:1}},{key:"minusDi",type:"line",title:"-DI",style:{color:"#ff5252",lineWidth:1}}],levels:()=>[{price:25,title:"Strong Trend Threshold",color:"#787b86",dashed:!0}],calc(t,R){const a=1/Math.max(1,Math.floor(Number(R.period)||14)),W=1-a,b=new Array(t.length).fill(NaN),x=new Array(t.length).fill(NaN),g=new Array(t.length).fill(NaN);let M=!0,d=1,u=0,r=0,m=0;for(let e=0;e<t.length;e+=1){const o=t[e].high,s=t[e].low;if(!Number.isFinite(o)||!Number.isFinite(s))continue;const f=e>0?t[e-1].close:NaN,w=e>0?t[e-1].high:NaN,F=e>0?t[e-1].low:NaN;let N=0,v=0,k=0;if(!Number.isFinite(f))N=o-s;else if(N=Math.max(o-s,Math.max(Math.abs(o-f),Math.abs(s-f))),Number.isFinite(w)&&Number.isFinite(F)){const l=o-w,i=F-s;l>i&&l>0&&(v=l),i>l&&i>0&&(k=i)}u+=a*(N-u),r+=a*(v-r),m+=a*(k-m);let n,D,y;if(M){d*=W;const l=1-d,i=l!==0?1/l:1;n=i*u,D=i*r,y=i*m,M=d>1e-10}else n=u,D=r,y=m;const c=n!==0?100*D/n:0,p=n!==0?100*y/n:0,A=c+p,E=A!==0?100*Math.abs(c-p)/A:0;Number.isFinite(c)&&(x[e]=c),Number.isFinite(p)&&(g[e]=p),Number.isFinite(E)&&(b[e]=E)}return{dx:h(b),plusDi:h(x),minusDi:h(g)}}})}export{S as default};
